companion_edits.new:
// Local MPL-2.0 correction: library-owned lanes close deterministically.
// Other caller threads use GC-managed arenas, not permanent global storage.
private static final ThreadLocal<java.lang.foreign.MemorySegment> REUSABLE_STATUS = new ThreadLocal<>();

private static java.lang.foreign.MemorySegment uniffiCallStatus() {
    java.lang.foreign.MemorySegment status = REUSABLE_STATUS.get();
    if (status == null) {
        status = java.lang.foreign.Arena.ofAuto().allocate(UniffiRustCallStatus.LAYOUT);
        REUSABLE_STATUS.set(status);
    }
    return status;
}

static void uniffiRunWithOwnedStatus(Runnable task) {
    java.lang.foreign.MemorySegment previous = REUSABLE_STATUS.get();
    try (java.lang.foreign.Arena arena = java.lang.foreign.Arena.ofConfined()) {
        REUSABLE_STATUS.set(arena.allocate(UniffiRustCallStatus.LAYOUT));
        try {
            task.run();
        } finally {
            if (previous == null) REUSABLE_STATUS.remove();
            else REUSABLE_STATUS.set(previous);
        }
    }
}

