public static void free(java.lang.foreign.MemorySegment buffer) {
    // Local MPL-2.0 correction: preserve descriptors that alias reusable call status.
    try (java.lang.foreign.Arena arena = java.lang.foreign.Arena.ofConfined()) {
        java.lang.foreign.MemorySegment stable = arena.allocate(LAYOUT);
        java.lang.foreign.MemorySegment.copy(buffer, 0, stable, 0, LAYOUT.byteSize());
        UniffiHelpers.uniffiRustCall((_allocator, status) -> {
            UniffiLib.ffi_lox_archive_rustbuffer_free(stable, status);
            return null;
        });
    }
}
